    def add_ocp_release(self, *, release_url, registry_images_url=None, registry_metadata_url=None, registry_namespace_id=None,
                        credentials=None, operations=None, agent_mode=False, raw=True, registry_check=True, timeout=60):
        """
        Add a new software release.

        :param str release_url: Mandatory, URL of the software release.
        :param str registry_metadata_url: URL of the registry metadata.
        :param str registry_images_url: URL of the registry images.
        :param str registry_namespace_id: UID of the container registry namespace.
        :param str credentials: Authentication credentials for accessing the release (username:password).
        :param str operations: Comma-separated list of operations to be performed on the release, e.g. ``download,add``.
             Available values:

             - ``download``: Mandatory, downloads the release to NEAT.
             - ``upload``: uploads the release to the container registry.
             - ``populate``: creates and stores a metadata file in harbor.
             - ``add``: adds the release to NEAT SW Manager.
             - ``push``: pushes the release to the git.
        :param bool raw: Optional, turns off OpenAPI deserialization. The default value is True.
        :param bool agent_mode: Optional, selector if agent-based installer binaries should be extracted from the release. Default is False.
        :param bool registry_check: Optional, check registry before adding release. Default is True.
        :param NEATConnection neat_connection: string name alias if used.
        :param Union[int, str] timeout: Optional, timeout in seconds for request, default is '60s'.

        .. warning:: Only one of either **registry_metadata_url** or **registry_images_url** is allowed
           to be passed along with **release_url**.

           All parameters must be passed as keyword arguments.

        :return: Dictionary of the added software release,
            for example::

                {
                    "data": {
                        "type": "releases",
                        "id": "stringstringstringstringstringstring",
                        "attributes": {
                            "releaseId": "string",
                            "version": "string",
                            "build": "string",
                            "releaseDate": "2024-12-10T05:32:17Z"
                        }
                    }
                }
        """
        return self._neat.add_ocp_release(
            registry_namespace_id=registry_namespace_id,
            release_url=release_url,
            registry_images_url=registry_images_url,
            registry_metadata_url=registry_metadata_url,
            credentials=base64_utils.encode_base64_string(credentials),
            operations=operations,
            agent_mode=agent_mode,
            raw=raw,
            registry_check=registry_check,
            timeout=timeout
        )

    def get_active_cloud_alarms(self, raw=True, timeout=60, **kwargs):
        """
        Get active cloud alarms.

        :param boolean raw: Optional, turns off OpenAPI deserialization. The default value is True.
        :param Union[int,str] timeout: Optional, timeout in seconds for request, default is '60s'.
        The following are part of kwargs:
        :param list[str] fields: Optional, limit cloud alarm attributes that are returned in response.
            Available values: 'alarmSeverities', 'alarmIds', 'cloudAlarmLevels'
            i.e. fields=['alarmSeverities', 'alarmIds']
        :param list[str] groups: Optional, filter analytics result based on cloud groups.
            A format must be valid group UUID. Multiple group UUIDs can be specified.
            UUIDs can be separated with a comma. Multiple "groups" -query filters can also be specified.
            Groups-filters and clouds-filters are executed before other analytics filters.
            i.e. groups=['17c51079-264d-52ba-832a-0df69d094198']
        :param list[str] clouds: Optional, filter analytics result based on cloud UUIDs.
            A format must be valid cloud UUID. Multiple cloud UUIDs can be specified.
            UUIDs can be separated with a comma. Multiple "clouds" -query filters can
            also be specified.
            Groups-filters and clouds-filters are executed before other analytics filters.
            i.e. clouds=['17c51079-264d-52ba-832a-0df69d094198']
        :param str alarmids: Optional, filter alarm analytics based on alarm ID.
            Multiple alarm IDs can be specified. Alarm IDs can be separated with a comma. Multiple "alarmids" -query filters can also be specified.
            i.e. alarmids='50011'
        :param list[str] severity: Optional, filter alarm analytics based on alarm severity.
            Available values: 'warning', 'minor', 'major', 'critical'
            Multiple severity levels can be specified. Severity levels can be separated with a comma.
            Multiple "severity" -query filters can also be specified.
        :param str before: Optional, filter alarm analytics by showing only alarms before the given timestamp.
            Multiple "before" filters cannot be specified.
            i.e. before='2019-03-13T00:00:01.123Z'
        :param str after: Optional, filter alarm analytics by showing only alarms after the given timestamp.
            Multiple "after" filters cannot be specified.
            i.e. after='2019-03-13T00:00:01.123Z'
        :return: List of active cloud alarms.
            Detailed information can refer to
            https://gitlabe2.ext.net.nokia.com/ucim/sw-manager/-/blob/master/apis/northbound/doc/openapi.yaml
            i.e.
            ::

            {
              "data": {
            "type": "alarmAnalytics",
            "id": "stringstringstringstringstringstring",
            "attributes": {
              "alarmSeverities": {
                "warning": 0,
                "minor": 0,
                "major": 0,
                "critical": 0,
                "total": 0
              },
              "alarmIds": {
                "<alarm-id>": 0,
                "<alarm-id2>": 0,
                "total": 0
              },
              "cloudAlarmLevels": {
                "ok": 0,
                "warning": 0,
                "minor": 0,
                "major": 0,
                "critical": 0,
                "unknown": 0,
                "total": 0
              }
            }
              },
              "links": {
            "self": "http://example.com"
              }
            }
        """
        return self._neat.get_active_cloud_alarms(timeout=int(timeout), raw=raw, **kwargs)

