    def get_alarm_analytics(self, *, fields="", groups="", clouds="", alarmids="", severity="", before="",
                            after="", timeout=60):
        """
        Get alarm analytics.

        .. admonition:: API used:

           GET `/neat/ucim/api/cloud-manager/v1/analytics/alarms`_

           .. _/neat/ucim/api/cloud-manager/v1/analytics/alarms:
            https://gitlabe2.ext.net.nokia.com/ucim/ucim/-/blob/master/apis/rest/cloud/doc/openapi.yaml

        :param NEATConnection neat_connection: string name alias if used.
        :param str timeout: Optional, timeout in seconds for request.
        :param str fields: Optional, a string representing comma-separated list of cloud alarm attributes to return in response.
            Available values: 'alarmSeverities', 'alarmIds', 'cloudAlarmLevels'
            i.e. fields='alarmSeverities,alarmIds'
        :param str groups: Optional, a string representing comma-separated list of cloud group UUIDs to filter analytics result based on.
            A format must be valid group UUID. Multiple group UUIDs can be specified.
            UUIDs can be separated with a comma. Multiple "groups" -query filters can also be specified.
            Groups-filters and clouds-filters are executed before other analytics filters.
            i.e. groups='17c51079-264d-52ba-832a-0df69d094198,17c51079-264d-52ba-832a-0df69d094199'
        :param str clouds: Optional, a string representing comma-separated list of cloud UUIDs to filter analytics result based on.
            A format must be valid cloud UUID. Multiple cloud UUIDs can be specified.
            UUIDs can be separated with a comma. Multiple "clouds" -query filters can also be specified.
            Groups-filters and clouds-filters are executed before other analytics filters.
            i.e. clouds='17c51079-264d-52ba-832a-0df69d094198,17c51079-264d-52ba-832a-0df69d094199'
        :param str alarmids: Optional, filter alarm analytics based on alarm ID.
            Multiple alarm IDs can be specified. Alarm IDs can be separated with a comma.
            Multiple 'alarmids' -query filters can also be specified.
            i.e. alarmids='50011'
        :param str severity: Optional, a string representing comma-separated list of alarm severities to filter analytics result based on.
            Available values: 'warning', 'minor', 'major', 'critical'
            i.e. severity='warning,minor'
            Multiple severity levels can be specified. Severity levels can be separated with a comma.
            Multiple "severity" -query filters can also be specified.
        :param str before: Optional, filter alarm analytics by showing only alarms before the given timestamp.
            Multiple 'before' filters cannot be specified.
            i.e. before='2019-03-13T00:00:01.123Z'
        :param str after: Optional, filter alarm analytics by showing only alarms after the given timestamp.
            Multiple 'after' filters cannot be specified.
            i.e. after='2019-03-13T00:00:01.123Z'

        Return value example: get_alarm_analytics.json_
          .. _get_alarm_analytics.json: ../example/response_examples.html#get-alarm-analytics-json
        """
        return self._neat.get_alarm_analytics(fields=fields, groups=groups, clouds=clouds, alarmids=alarmids, severity=severity,
                                              before=before, after=after, timeout=int(timeout))

